scripts.value-tests.zig:
test "VALUE direct call preserves bounds capacity failure PC and frame state" {
    for ([_]bool{false, true}) |counted| {
        for ([_]bool{false, true}) |pending| {
            for ([_]usize{0, 1, 2}) |free| {
                for ([_]i32{-1, 0, 1, 7, 8}) |offset| {
                    var output = Output{};
                    const machine = try createMachine(&output);
                    defer destroyMachine(machine);
                    machine.keep_counting = counted;
                    try machine.interpretLine("123 VALUE VALUE-UNDER-TEST : VALUE-PREFIX ; : VALUE-TRIAL VALUE-PREFIX VALUE-UNDER-TEST ;");
                    const value_id = try machine.lookupOrFail("VALUE-UNDER-TEST");
                    const id = try machine.lookupOrFail("VALUE-TRIAL");
                    var target_pc: ?usize = null;
                    for (machine.words[id].code_start..machine.words[id].code_end) |pc| {
                        if (machine.code[pc].kind == .call and machine.code[pc].value == value_id) target_pc = pc;
                    }
                    const pc = target_pc orelse return error.TestUnexpectedResult;
                    try std.testing.expect(pc > machine.words[id].code_start);
                    const address: forth.Cell = if (offset < 0) -1 else @as(forth.Cell, @intCast(machine.memory.len)) - offset;
                    machine.words[value_id].value = address;
                    const valid = offset == 8;
                    if (valid) try machine.writeCell(address, 1234567);
                    @memset(machine.data_stack, -37);
                    const depth = machine.data_stack.len - free;
                    machine.data_depth = depth;
                    machine.return_stack[0] = 41; machine.return_stack[1] = 42; machine.return_depth = 2;
                    machine.float_stack[0] = 1.5; machine.float_depth = 1;
                    machine.output_error = if (pending) -88 else null;
                    const locals = machine.locals_top;
                    if (!valid) {
                        try std.testing.expectError(error.InvalidAddress, machine.executeWord(id));
                    } else if (free == 0) {
                        try std.testing.expectError(error.StackOverflow, machine.executeWord(id));
                    } else try machine.executeWord(id);
                    const success = valid and free != 0;
                    try std.testing.expectEqual(depth + @intFromBool(success), machine.data_depth);
                    for (machine.data_stack[0..depth]) |value| try std.testing.expectEqual(@as(forth.Cell, -37), value);
                    if (success) try std.testing.expectEqual(@as(forth.Cell, 1234567), machine.data_stack[depth]);
                    for (machine.data_stack[machine.data_depth..]) |value| try std.testing.expectEqual(@as(forth.Cell, -37), value);
                    try std.testing.expectEqual(@as(usize, 2), machine.return_depth);
                    try std.testing.expectEqualSlices(forth.Cell, &.{41,42}, machine.return_stack[0..2]);
                    try std.testing.expectEqual(@as(usize, 1), machine.float_depth);
                    try std.testing.expectEqual(@as(forth.Float, 1.5), machine.float_stack[0]);
                    try std.testing.expectEqual(locals, machine.locals_top);
                    try std.testing.expectEqual(@as(usize, 0), machine.frame_depth);
                    try std.testing.expectEqual(@as(usize, 0), machine.call_depth);
                    try std.testing.expectEqual(@as(usize, 0), machine.catch_depth);
                    try std.testing.expectEqual(@as(?forth.Cell, if (pending) -88 else null), machine.output_error);
                    if (@import("../core/defs.zig").debug_enabled) {
                        try std.testing.expectEqual(@as(u16, @intCast(pc + 1)), machine.outer_pc);
                        if (!success) try std.testing.expectEqual(@as(u16, @intCast(pc + 1)), machine.failed_pc);
                    }
                }
            }
        }
    }
