test "literal AND trial preserves partial stacks errors and failed PC" {
    for ([_]bool{ false, true }) |counted| {
        for ([_]bool{ false, true }) |pending| {
            for ([_]enum { empty, one, two, one_free, full }{ .empty, .one, .two, .one_free, .full }) |which_depth| {
                var output = Output{};
                const machine = try createMachine(&output);
                defer destroyMachine(machine);
                const depth: usize = switch (which_depth) {
                    .empty => 0,
                    .one => 1,
                    .two => 2,
                    .one_free => machine.data_stack.len - 1,
                    .full => machine.data_stack.len,
                };
                machine.keep_counting = counted;
                try machine.interpretLine(": FUSION-PROBE 255 AND ;");
                const id = try machine.lookupOrFail("FUSION-PROBE");
                const pc = machine.words[id].code_start;
                try std.testing.expectEqual(@import("../core/defs.zig").OpKind.literal, machine.code[pc].kind);
                try std.testing.expectEqual(@import("../core/defs.zig").OpKind.bit_and, machine.code[pc + 1].kind);
                @memset(machine.data_stack, -37);
                machine.data_depth = depth;
                machine.return_stack[0] = 41;
                machine.return_depth = 1;
                machine.float_stack[0] = 1.5;
                machine.float_depth = 1;
                machine.output_error = if (pending) -88 else null;
                const locals = machine.locals_top;
                const full = depth == machine.data_stack.len;
                if (full) try std.testing.expectError(error.StackOverflow, machine.executeWord(id)) else if (depth == 0) try std.testing.expectError(error.StackUnderflow, machine.executeWord(id)) else try machine.executeWord(id);
                const after = depth;
                try std.testing.expectEqual(after, machine.data_depth);
                if (depth == 0) try std.testing.expectEqual(@as(forth.Cell, 255), machine.data_stack[0]) else if (!full) {
                    for (machine.data_stack[0 .. depth - 1]) |x| try std.testing.expectEqual(@as(forth.Cell, -37), x);
                    try std.testing.expectEqual(@as(forth.Cell, -37 & 255), machine.data_stack[depth - 1]);
                } else for (machine.data_stack) |x| try std.testing.expectEqual(@as(forth.Cell, -37), x);
                try std.testing.expectEqual(@as(usize, 1), machine.return_depth);
                try std.testing.expectEqual(@as(forth.Cell, 41), machine.return_stack[0]);
                try std.testing.expectEqual(@as(usize, 1), machine.float_depth);
                try std.testing.expectEqual(@as(forth.Float, 1.5), machine.float_stack[0]);
                try std.testing.expectEqual(locals, machine.locals_top);
                try std.testing.expectEqual(@as(usize, 0), machine.call_depth);
                try std.testing.expectEqual(@as(usize, 0), machine.frame_depth);
                try std.testing.expectEqual(@as(?forth.Cell, if (pending) -88 else null), machine.output_error);
                if (@import("../core/defs.zig").debug_enabled and (full or depth == 0)) try std.testing.expectEqual(pc + @as(u16, if (full) 1 else 2), machine.failed_pc);
            }
        }
    }
}

